<template><div class="cases-view"><div class="toolbar"><el-button type="primary" @click="router.push('/create')"><el-icon><Plus /></el-icon>新建用例</el-button><el-button @click="refresh"><el-icon><Refresh /></el-icon></el-button></div><div class="workspace"><aside class="directory-panel"><div class="directory-head">用例目录<el-button text :icon="Plus" :disabled="!projectId" @click="openDirectoryDialog" /></div><el-tree :data="directoryTreeData" node-key="id" :props="{label:'name',children:'children'}" @node-click="selectDirectory" /></aside><section class="case-panel"><div class="filters"><span>{{ selectedDirectoryName||'全部目录' }}</span><el-input v-model="keyword" placeholder="按用例名称搜索" clearable :prefix-icon="Search" /></div><el-table :data="filteredCases" v-loading="loading" stripe><el-table-column prop="name" label="用例名称" min-width="180"><template #default="{row}"><el-link type="primary" @click="router.push(`/detail/${row.id}`)">{{row.name||row.id}}</el-link></template></el-table-column><el-table-column label="登录方式" min-width="150"><template #default="{row}"><span v-if="loginMethodOf(row)">{{ loginMethodOf(row)!.type === 'cas' ? 'CAS 登录' : '本地登录' }}（{{ loginMethodOf(row)!.username }}）</span><el-tag v-else size="small" type="info">免登录</el-tag></template></el-table-column><el-table-column prop="status" label="状态" width="100"><template #default="{row}"><el-tag :type="statusType(row.status)">{{statusName(row.status)}}</el-tag></template></el-table-column><el-table-column prop="createdAt" label="创建时间" width="165"><template #default="{row}">{{formatTime(row.createdAt)}}</template></el-table-column><el-table-column label="操作" width="230"><template #default="{row}"><el-button link type="primary" @click="router.push(`/detail/${row.id}`)">详情</el-button><el-button link type="success" @click="execute(row)">执行</el-button><el-button link @click="viewCache(row)">查看缓存</el-button><el-button link type="danger" @click="removeCase(row)">删除</el-button></template></el-table-column></el-table></section></div><el-dialog v-model="directoryDialog" title="新增目录" width="400px"><el-input v-model="directoryName" placeholder="目录名称" /><template #footer><el-button @click="directoryDialog=false">取消</el-button><el-button type="primary" @click="createDirectory">创建</el-button></template></el-dialog><el-dialog v-model="cacheDialog" title="Midscene 缓存" width="760px"><el-input v-model="cacheText" type="textarea" :rows="18" readonly /></el-dialog></div></template>
<script setup lang="ts">import{computed,onMounted,ref,watch}from'vue';import{useRouter}from'vue-router';import{ElMessage,ElMessageBox}from'element-plus';import{Plus,Refresh,Search}from'@element-plus/icons-vue';import{useCaseStore,useConfigStore,useProjectStore}from'@/stores';import{createCaseDirectory,getCaseDirectories,getCaseCache,getLoginMethods,type CaseDirectory,type LoginMethod}from'@/api/cases';const router=useRouter(),caseStore=useCaseStore(),projectStore=useProjectStore(),configStore=useConfigStore(),directories=ref<CaseDirectory[]>([]),selectedDirectoryId=ref(''),selectedDirectoryName=ref(''),keyword=ref(''),loading=ref(false),directoryDialog=ref(false),directoryName=ref(''),cacheDialog=ref(false),cacheText=ref('');const projectId=computed(()=>projectStore.currentProject?.id||'');const loginMethods=ref<LoginMethod[]>([]);const loginMethodOf=(row:any)=>row.loginMethodId?loginMethods.value.find(m=>m.id===row.loginMethodId):undefined;const directoryTreeData=computed(()=>{const nodes:any={};directories.value.forEach(d=>nodes[d.id]={...d,children:[]});return directories.value.filter(d=>!d.parentId).map(d=>nodes[d.id]).map((root:any)=>{const fill=(node:any)=>{node.children=directories.value.filter(d=>d.parentId===node.id).map(d=>nodes[d.id]);node.children.forEach(fill)};fill(root);return root})});const filteredCases=computed(()=>caseStore.cases.filter((c:any)=>(!projectId.value||c.projectId===projectId.value)&&(!selectedDirectoryId.value||c.directoryId===selectedDirectoryId.value)&&(!keyword.value||(c.name||'').toLowerCase().includes(keyword.value.toLowerCase()))));const loadDirectories=async()=>{directories.value=projectId.value?await getCaseDirectories(projectId.value):[]};const loadLoginMethods=async()=>{loginMethods.value=projectId.value?await getLoginMethods(projectId.value):[]};const selectDirectory=(d:CaseDirectory)=>{selectedDirectoryId.value=d.id;selectedDirectoryName.value=d.name};const openDirectoryDialog=()=>{directoryName.value='';directoryDialog.value=true};const createDirectory=async()=>{if(!directoryName.value.trim())return ElMessage.warning('请输入目录名称');await createCaseDirectory({projectId:projectId.value,name:directoryName.value.trim()});directoryDialog.value=false;await loadDirectories()};const removeCase=async(row:any)=>{try{await ElMessageBox.confirm(`确认删除用例“${row.name}”吗？`,'删除用例',{type:'warning'});await caseStore.removeCase(row.id)}catch{}};const execute=async(row:any)=>{const r:any=await caseStore.runCase(row.id,undefined,configStore.aiConfig.browserMode==='headless');r?.executionId?ElMessage.success('执行任务已提交'):ElMessage.error(r?.response?.data?.error||r?.errorDetail||'执行失败')};const viewCache=async(row:any)=>{try{cacheText.value=await getCaseCache(row.id);cacheDialog.value=true}catch{ElMessage.info('该用例暂无缓存文件')}};const statusType=(s:string)=>({SUCCESS:'success',FAILED:'danger',RUNNING:'warning',PENDING:'info'}as any)[s]||'info',statusName=(s:string)=>({SUCCESS:'成功',FAILED:'失败',RUNNING:'执行中',PENDING:'未执行'}as any)[s]||s,formatTime=(v:string)=>v?v.replace('T',' ').slice(0,16):'-';const refresh=async()=>{loading.value=true;try{await Promise.all([caseStore.fetchCases(),loadDirectories(),loadLoginMethods()])}finally{loading.value=false}};watch(projectId,refresh,{immediate:true});onMounted(async()=>{await Promise.all([projectStore.fetchProjects(),caseStore.fetchCases(),configStore.fetchAIConfig()])})</script>
<style scoped lang="scss">.toolbar,.workspace{background:#fff;border-radius:8px;box-shadow:0 2px 12px rgba(0,0,0,.08)}.toolbar{display:flex;justify-content:flex-end;gap:8px;padding:14px;margin-bottom:16px}.workspace{display:grid;grid-template-columns:260px 1fr;min-height:620px}.directory-panel{padding:16px;border-right:1px solid #eee}.directory-head{display:flex;justify-content:space-between;font-weight:600}.case-panel{padding:16px;min-width:0}.filters{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.filters .el-input{max-width:320px}</style>
